sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    var user = new GlideRecord('sys_user');
    user.get(newValue);
    if (user.vip == 'true') {
        alert('Caller is a VIP');
    }
    var caller = g_form.getReference('caller_id');
    g_form.setValue('location', caller.location);
    var manager = g_form.getReference('assigned_to');
    g_form.setValue('company', manager.company);
    var group = new GlideRecord('sys_user_group');
    group.get(g_form.getValue('assignment_group'));
    if (!group.active) {
        alert('The assignment group is inactive');
    }
    alert('Caller details updated');
}
